1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials",
24	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
25	            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
26	    @Mapping(target = "telephoneDisplay",
27	        expression = "java(telephoneDisplay(owner))")
28	    @Mapping(target = "membershipNumber",
29	        expression = "java(membershipNumber(owner))")
30	    @Mapping(target = "membershipPoints",
31	        expression = "java(membershipPoints(owner))")
32	    @Mapping(target = "membershipLevel",
33	        expression = "java(membershipLevel(owner))")
34	    @Mapping(target = "locality",
35	        expression = "java(locality(owner))")
36	    @Mapping(target = "timezone",
37	        expression = "java(timezone(owner))")
38	    @Mapping(target = "contactPreference",
39	        expression = "java(contactPreference(owner))")
40	    @Mapping(target = "identityKey",
41	        expression = "java(identityKey(owner))")
42	    @Mapping(target = "checkDigit",
43	        expression = "java(checkDigit(owner))")
44	    @Mapping(target = "ageBand",
45	        expression = "java(ageBand(owner))")
46	    @Mapping(target = "fiscalYear",
47	        expression = "java(fiscalYear(owner))")
48	    @Mapping(target = "salutation",
49	        expression = "java(salutation(owner))")
50	    @Mapping(target = "selfLink",
51	        expression = "java(selfLink(owner))")
52	    @Mapping(target = "ownerSegment",
53	        expression = "java(ownerSegment(owner))")
54	    @Mapping(target = "sharesHousehold", ignore = true)
55	    OwnerDto toOwnerDto(Owner owner);
56	
57	    /**
58	     * Build the owner's canonical self link: '/api/owners/' followed by the owner's id. Returns null
59	     * when the owner has no id so an unsaved owner serializes cleanly.
60	     */
61	    default String selfLink(Owner owner) {
62	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
63	    }
64	
65	    /**
66	     * The set of known regions treated as METRO when deriving an owner's segment area.
67	     */
68	    java.util.Set<String> METRO_REGIONS = java.util.Set.of("NSW", "VIC", "QLD");
69	
70	    /**
71	     * Derive the owner's segment, formatted '&lt;TIER&gt;_&lt;AREA&gt;'. TIER is 'PREMIUM' when
72	     * {@link #membershipLevel(Owner)} is 3 or more, otherwise 'STANDARD'. AREA is 'METRO' when the
73	     * {@link #locality(Owner)} is a known region (NSW, VIC or QLD), otherwise 'REGIONAL'.
74	     */
75	    default String ownerSegment(Owner owner) {
76	        String tier = membershipLevel(owner) >= 3 ? "PREMIUM" : "STANDARD";
77	        String area = METRO_REGIONS.contains(locality(owner)) ? "METRO" : "REGIONAL";
78	        return tier + "_" + area;
79	    }
80	
81	    /**
82	     * Build the owner's salutation: the honorific title followed by a single space and the last name
83	     * (e.g. 'DR Who') when a title is present, or just the last name when no title was supplied. A
84	     * blank title is treated as absent.
85	     */
86	    default String salutation(Owner owner) {
87	        String lastName = owner.getLastName();
88	        String title = owner.getTitle();
89	        if (title == null || title.trim().isEmpty()) {
90	            return lastName;
91	        }
92	        return title + " " + lastName;
93	    }
94	
95	    /**
96	     * Derive the owner's age band from the supplied birthDate, evaluated against the owner's
97	     * registrationDate: 'MINOR' when under 18, 'ADULT' when 18 to 64 inclusive, and 'SENIOR' when
98	     * 65 or older. Returns null when no birthDate was supplied (or no registrationDate is available)
99	     * so owners without a birth date serialize cleanly.
100	     */
101	    default String ageBand(Owner owner) {
102	        java.time.LocalDate birthDate = owner.getBirthDate();
103	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
104	        if (birthDate == null || registrationDate == null) {
105	            return null;
106	        }
107	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
108	        if (age < 18) {
109	            return "MINOR";
110	        }
111	        if (age < 65) {
112	            return "ADULT";
113	        }
114	        return "SENIOR";
115	    }
116	
117	    /**
118	     * The E.164 country calling codes whose split from the national number is recognised when
119	     * formatting {@code telephoneDisplay} (matching the codes validated on create). The longest
120	     * matching code wins so a shorter code that is a prefix of another cannot mask it.
121	     */
122	    java.util.Set<String> KNOWN_COUNTRY_CODES = java.util.Set.of("1", "61");
123	
124	    /**
125	     * Format the stored E.164 telephone for humans: the '+' and country calling code, a space, then
126	     * the national digits grouped in threes (e.g. '+61412345678' -&gt; '+61 412 345 678'). The
127	     * country code is split off using the recognised calling codes; when none matches, a single-digit
128	     * code is assumed so the value is still rendered as '+&lt;code&gt; &lt;grouped national&gt;'.
129	     * Returns the stored value unchanged when it is null or not in E.164 form.
130	     */
131	    default String telephoneDisplay(Owner owner) {
132	        String telephone = owner.getTelephone();
133	        if (telephone == null || !telephone.startsWith("+")) {
134	            return telephone;
135	        }
136	        String digits = telephone.substring(1);
137	        if (!digits.matches("\\d+")) {
138	            return telephone;
139	        }
140	        String countryCode = digits.substring(0, 1);
141	        String national = digits.substring(1);
142	        for (int codeLength = Math.min(3, digits.length() - 1); codeLength >= 1; codeLength--) {
143	            String candidate = digits.substring(0, codeLength);
144	            if (KNOWN_COUNTRY_CODES.contains(candidate)) {
145	                countryCode = candidate;
146	                national = digits.substring(codeLength);
147	                break;
148	            }
149	        }
150	        StringBuilder grouped = new StringBuilder();
151	        for (int i = 0; i < national.length(); i++) {
152	            if (i > 0 && i % 3 == 0) {
153	                grouped.append(' ');
154	            }
155	            grouped.append(national.charAt(i));
156	        }
157	        return "+" + countryCode + " " + grouped;
158	    }
159	
160	    /**
161	     * Compute the owner's check digit: a single Luhn check digit (0-9) over the digits contained in
162	     * the customerCode. Returns null when no customerCode has been assigned so owners without a code
163	     * serialize cleanly.
164	     */
165	    default Integer checkDigit(Owner owner) {
166	        String customerCode = owner.getCustomerCode();
167	        if (customerCode == null) {
168	            return null;
169	        }
170	        int sum = 0;
171	        boolean dbl = true;
172	        for (int i = customerCode.length() - 1; i >= 0; i--) {
173	            char c = customerCode.charAt(i);
174	            if (c < '0' || c > '9') {
175	                continue;
176	            }
177	            int d = c - '0';
178	            if (dbl) {
179	                d *= 2;
180	                if (d > 9) {
181	                    d -= 9;
182	                }
183	            }
184	            sum += d;
185	            dbl = !dbl;
186	        }
187	        return (10 - (sum % 10)) % 10;
188	    }
189	
190	    /**
191	     * Derive the owner's identity key, the single value into which all duplicate detection is
192	     * consolidated: the full lower-case hex SHA-256 over
193	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. Two owners are
194	     * duplicates only when their whole identity keys are equal. A null email or last name contributes
195	     * an empty segment.
196	     */
197	    default String identityKey(Owner owner) {
198	        return IdentityKeys.identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
199	    }
200	
201	    /**
202	     * Determine the owner's preferred contact channel: 'EMAIL' when an email address is present,
203	     * otherwise 'PHONE'.
204	     */
205	    default String contactPreference(Owner owner) {
206	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
207	        return hasEmail ? "EMAIL" : "PHONE";
208	    }
209	
210	    /**
211	     * The calendar year in which the fiscal year containing {@code date} starts. The fiscal year
212	     * starts on 1 July, so dates in July through December map to their own calendar year while
213	     * dates in January through June map to the previous calendar year.
214	     */
215	    static int fiscalYearStart(java.time.LocalDate date) {
216	        return date.getMonthValue() >= java.time.Month.JULY.getValue()
217	            ? date.getYear() : date.getYear() - 1;
218	    }
219	
220	    /**
221	     * Derive the owner's fiscal year from the (business-day-adjusted) registrationDate, formatted
222	     * 'FY&lt;YY&gt;' where YY is the last two digits of the fiscal year's starting calendar year. The
223	     * fiscal year starts on 1 July. Returns null when no registrationDate is available so owners
224	     * without one serialize cleanly.
225	     */
226	    default String fiscalYear(Owner owner) {
227	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
228	        if (registrationDate == null) {
229	            return null;
230	        }
231	        return String.format("FY%02d", fiscalYearStart(registrationDate) % 100);
232	    }
233	
234	    /**
235	     * Build the owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is
236	     * the last two digits of the fiscal year (see {@link #fiscalYear(Owner)}) derived from the
237	     * business-day-adjusted registrationDate. Returns null when either source field is absent so
238	     * owners without an assigned code or registration date serialize cleanly.
239	     */
240	    default String membershipNumber(Owner owner) {
241	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
242	            return null;
243	        }
244	        return String.format("%s-M%02d", owner.getCustomerCode(),
245	            fiscalYearStart(owner.getRegistrationDate()) % 100);
246	    }
247	
248	    /**
249	     * Compute the owner's membership points. Starts at 0; add 2 when an email address is present;
250	     * add 1 when the owner has no namesakes (namesakeCount is 0); add 2 for a household of 3 or more
251	     * (householdSize); add 3 for tenure of at least one elapsed fiscal year, measured as the number
252	     * of fiscal-year starts (1 July) between the registrationDate and the current date. Because a
253	     * newly created owner has zero elapsed fiscal years, a new owner never earns the tenure points.
254	     */
255	    default Integer membershipPoints(Owner owner) {
256	        int points = 0;
257	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
258	        if (hasEmail) {
259	            points += 2;
260	        }
261	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
262	        if (noNamesakes) {
263	            points += 1;
264	        }
265	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
266	            points += 2;
267	        }
268	        if (owner.getRegistrationDate() != null
269	                && fiscalYearStart(java.time.LocalDate.now())
270	                    - fiscalYearStart(owner.getRegistrationDate()) >= 1) {
271	            points += 3;
272	        }
273	        return points;
274	    }
275	
276	    /**
277	     * Determine the owner's numeric membership level, derived from membershipPoints: 1 for 0-1
278	     * points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points. The points-derived
279	     * level is then capped by {@code membershipLevelCap} when one was assigned at creation: a new
280	     * owner's level may not exceed one above the highest level among their existing household
281	     * members. When no cap was assigned (no existing household member), the points-derived level is
282	     * returned unchanged.
283	     */
284	    default Integer membershipLevel(Owner owner) {
285	        int points = membershipPoints(owner);
286	        int level;
287	        if (points <= 1) {
288	            level = 1;
289	        } else if (points <= 3) {
290	            level = 2;
291	        } else if (points <= 5) {
292	            level = 3;
293	        } else {
294	            level = 4;
295	        }
296	        Integer cap = owner.getMembershipLevelCap();
297	        if (cap != null && level > cap) {
298	            level = cap;
299	        }
300	        return level;
301	    }
302	
303	    /**
304	     * The fixed city-to-region table used to derive an owner's locality when the postcode is absent
305	     * or falls in no known range.
306	     */
307	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
308	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
309	
310	    /**
311	     * Region -&gt; inclusive 4-digit postcode range {low, high}: NSW 2000-2099, VIC 3000-3099,
312	     * QLD 4000-4099.
313	     */
314	    java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
315	        "NSW", new int[] {2000, 2099},
316	        "VIC", new int[] {3000, 3099},
317	        "QLD", new int[] {4000, 4099});
318	
319	    /**
320	     * Derive the owner's locality (canonical region), preferring the postcode: look up the region by
321	     * postcode range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), and only fall back to the
322	     * city-to-region table (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD) when the postcode is
323	     * absent or in no known range. Returns 'UNKNOWN' when neither source resolves a region.
324	     */
325	    default String locality(Owner owner) {
326	        String postcode = owner.getPostcode();
327	        if (postcode != null && postcode.matches("\\d{4}")) {
328	            int value = Integer.parseInt(postcode);
329	            for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
330	                int[] range = entry.getValue();
331	                if (value >= range[0] && value <= range[1]) {
332	                    return entry.getKey();
333	                }
334	            }
335	        }
336	        String city = owner.getCity();
337	        if (city == null) {
338	            return "UNKNOWN";
339	        }
340	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
341	    }
342	
343	    /**
344	     * The fixed region-to-timezone table used to derive an owner's timezone from its locality:
345	     * NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne, QLD-&gt;Australia/Brisbane.
346	     */
347	    java.util.Map<String, String> REGION_TIMEZONE = java.util.Map.of(
348	        "NSW", "Australia/Sydney",
349	        "VIC", "Australia/Melbourne",
350	        "QLD", "Australia/Brisbane");
351	
352	    /**
353	     * Derive the owner's timezone as an IANA name from its locality (canonical region) using the
354	     * fixed region-to-timezone table (NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne,
355	     * QLD-&gt;Australia/Brisbane). Returns null when the locality is not in the table so owners with
356	     * an unknown region serialize cleanly.
357	     */
358	    default String timezone(Owner owner) {
359	        return REGION_TIMEZONE.get(locality(owner));
360	    }
361	
362	    Owner toOwner(OwnerDto ownerDto);
363	
364	    @Mapping(target = "id", ignore = true)
365	    @Mapping(target = "pets", ignore = true)
366	    Owner toOwner(OwnerFieldsDto ownerDto);
367	
