76	@RestController
77	@CrossOrigin(exposedHeaders = "errors, content-type")
78	@RequestMapping("/api")
79	public class OwnerRestControllerV1 implements OwnersApi {
80	
81	    /** Dedicated audit logger; emits one line per successful owner create. */
82	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
83	
84	    /**
85	     * Process-wide, monotonically increasing sequence stamped onto each structured
86	     * {@code OWNER_CREATED} audit event so consumers can order and de-duplicate them.
87	     */
88	    private static final AtomicLong AUDIT_EVENT_SEQ = new AtomicLong();
89	
90	    /** Serializes structured audit events to compact JSON. */
91	    private static final ObjectMapper AUDIT_MAPPER = JsonMapper.builder().build();
92	
93	    private final ClinicService clinicService;
94	
95	    private final OwnerMapper ownerMapper;
96	
97	    private final PetMapper petMapper;
98	
99	    private final VisitMapper visitMapper;
100	
101	    /** HTTP header carrying the caller-supplied idempotency key for owner creates. */
102	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
103	
104	    /**
105	     * Records the owner created for each previously-seen idempotency key, so a create that repeats a
106	     * key returns the originally created owner instead of creating a duplicate. Keyed by the raw
107	     * header value; the stored value is the response returned for the first successful create.
108	     */
109	    private final Map<String, OwnerDto> idempotentCreations = new ConcurrentHashMap<>();
110	
111	    public OwnerRestControllerV1(ClinicService clinicService,
112	                                 OwnerMapper ownerMapper,
113	                                 PetMapper petMapper,
114	                                 VisitMapper visitMapper) {
115	        this.clinicService = clinicService;
116	        this.ownerMapper = ownerMapper;
117	        this.petMapper = petMapper;
118	        this.visitMapper = visitMapper;
119	    }
120	
121	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
122	    @Override
123	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
124	        Collection<Owner> owners;
125	        if (lastName != null) {
126	            owners = this.clinicService.findOwnerByLastName(lastName);
127	        } else {
128	            owners = this.clinicService.findAllOwners();
129	        }
130	        if (owners.isEmpty()) {
131	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
132	        }
133	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
139	        Owner owner = this.clinicService.findOwnerById(ownerId);
140	        if (owner == null) {
141	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
142	        }
143	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
144	    }
145	
146	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
147	    @Override
148	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
149	        // Idempotent create: when the request carries an 'Idempotency-Key' header that we have already
150	        // seen, return the owner originally created for that key with 200 instead of creating a
151	        // duplicate (which would otherwise be rejected as a 409 conflict). A brand-new key is recorded
152	        // below once the create succeeds; a request without the header is never treated as idempotent.
153	        String idempotencyKey = currentIdempotencyKey();
154	        if (idempotencyKey != null) {
155	            OwnerDto existing = idempotentCreations.get(idempotencyKey);
156	            if (existing != null) {
157	                return new ResponseEntity<>(existing, HttpStatus.OK);
158	            }
159	        }
160	        // Normalize the address up front so every downstream use (the required-field check,
161	        // household-duplicate detection, the shared household id and the stored/returned value)
162	        // works from the same canonical form. The structured 'addressLine1'/'addressLine2' fields are
163	        // preferred when present; the flat 'address' remains accepted for backward compatibility. Each
164	        // supplied line is normalized the same way, and the composed address is the normalized
165	        // addressLine1 with a single space and the normalized addressLine2 appended when present.
166	        String normalizedAddressLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
167	        String normalizedAddressLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
168	        boolean structuredAddress = !isBlank(normalizedAddressLine1);
169	        String normalizedAddress;
170	        if (structuredAddress) {
171	            normalizedAddress = normalizedAddressLine2.isEmpty()
172	                ? normalizedAddressLine1
173	                : normalizedAddressLine1 + " " + normalizedAddressLine2;
174	        } else {
175	            normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
176	        }
177	        List<String> missingFields = new ArrayList<>();
178	        if (isBlank(ownerFieldsDto.getFirstName())) {
179	            missingFields.add("firstName");
180	        }
181	        if (isBlank(ownerFieldsDto.getLastName())) {
182	            missingFields.add("lastName");
183	        }
184	        // Reject an address that is blank once normalized (e.g. whitespace-only input).
185	        if (isBlank(normalizedAddress)) {
186	            missingFields.add("address");
187	        }
188	        if (isBlank(ownerFieldsDto.getCity())) {
189	            missingFields.add("city");
190	        }
191	        if (isBlank(ownerFieldsDto.getTelephone())) {
192	            missingFields.add("telephone");
193	        }
194	        if (!missingFields.isEmpty()) {
195	            throw new InvalidOwnerFieldsException(missingFields);
196	        }
197	        // A supplied registration date may not lie in the future: reject with 400 when the caller
198	        // provides a date later than the server's current date. Checked against the raw supplied value
199	        // (before any business-day adjustment) so a future date is never silently accepted.
200	        if (ownerFieldsDto.getRegistrationDate() != null
201	            && ownerFieldsDto.getRegistrationDate().isAfter(LocalDate.now())) {
202	            throw new FutureRegistrationDateException(ownerFieldsDto.getRegistrationDate());
203	        }
204	        // Determine the effective registration date up front so every downstream use (the daily
205	        // create-limit, the stored value and anything derived from it such as the membership number's
206	        // year segment) works from the same business-day-adjusted date. The effective date is the
207	        // supplied value when present, otherwise the server's current date; a weekend date is rolled
208	        // forward to the following Monday.
209	        LocalDate effectiveRegistrationDate = ownerFieldsDto.getRegistrationDate() != null
210	            ? ownerFieldsDto.getRegistrationDate()
211	            : LocalDate.now();
212	        effectiveRegistrationDate = toBusinessDay(effectiveRegistrationDate);
213	        // Reject the request once the day's owner-creation limit is reached: when 100 or more owners
214	        // already carry this adjusted business day's registration date, no further owners may be
215	        // created for that day.
216	        int ownersRegisteredToday = countOwnersRegisteredOn(effectiveRegistrationDate);
217	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
218	            throw new DailyOwnerLimitExceededException(effectiveRegistrationDate);
219	        }
220	        // Flag a bulk signup once more than 80 owners have already been created for this
221	        // business day, sharing the same daily accumulation path as the create-limit rule above.
222	        boolean bulkSignupWarning = ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD;
223	        // Reject the request when the owner's city is already full: a city that already holds the
224	        // maximum of 50 owners (compared case-insensitively, as elsewhere) accepts no more.
225	        int ownersInCity = countOwnersInCity(ownerFieldsDto.getCity());
226	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
227	            throw new CityAtCapacityException(ownerFieldsDto.getCity());
228	        }
229	        // Flag a capacity warning when the owner's city is approaching the per-city limit: it already
230	        // holds between 40 and 49 owners (the hard rejection at 50 above is unchanged).
231	        boolean capacityWarning = ownersInCity >= CITY_CAPACITY_WARNING_THRESHOLD;
232	        // Postcode is optional; when present it must be a 4-digit value that is valid for the
233	        // owner's city per the fixed region ranges. A malformed or out-of-range postcode is
234	        // rejected with a 400. An absent postcode leaves the request contract unchanged.
235	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
236	        // Normalize the telephone into E.164 form; a number that cannot form a valid
237	        // E.164 value is rejected with a 400.
238	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
239	        // Email is optional; when present it must be a syntactically valid address and is
240	        // stored lower-cased. An invalid address is rejected with a 400.
241	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
242	        // Derive the household id up front. It is a deterministic function of the normalized last name
243	        // and the postcode, so owners sharing a last name and postcode independently derive the same
244	        // value and are the same household. It is always computed (never null), regardless of whether
245	        // the caller opts into a shared household; 'sharesHousehold' now only bypasses the household
246	        // duplicate block below.
247	        String normalizedLastName = collapse(ownerFieldsDto.getLastName());
248	        String householdId = householdId(normalizedLastName, ownerFieldsDto.getPostcode());
249	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
250	        // All duplicate detection is consolidated into a single derived identity key: the SHA-256 hex
251	        // over 'normalizedTelephone + | + lowerEmail + | + soundex(lastName)'. Because the telephone is
252	        // part of the key, two members of the same household (same last name and postcode) with
253	        // different telephones have different keys and are both allowed; only an exact whole-key match
254	        // is a duplicate. The email-domain blocklist has already been applied (during email
255	        // normalization above). Reject with 409 when a new owner's whole identity key equals an
256	        // existing (non-deleted) owner's. The computed householdId no longer contributes a separate
257	        // duplicate block; it is retained only for household grouping (size, level cap, points).
258	        String identityKey = identityKey(normalizedTelephone, normalizedEmail, ownerFieldsDto.getLastName());
259	        boolean identityInUse = this.clinicService.findAllOwners().stream()
260	            .filter(existing -> !existing.isDeleted())
261	            .anyMatch(existing -> identityKey.equals(
262	                identityKey(existing.getTelephone(), existing.getEmail(), existing.getLastName())));
263	        if (identityInUse) {
264	            throw new DuplicateOwnerIdentityException(identityKey);
265	        }
266	        HttpHeaders headers = new HttpHeaders();
267	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
268	        // Store the composed, normalized address plus the normalized structured lines. The structured
269	        // lines are only retained when the owner was supplied in the structured form; a flat-address
270	        // owner keeps them null.
271	        owner.setAddress(normalizedAddress);
272	        owner.setAddressLine1(structuredAddress ? normalizedAddressLine1 : null);
273	        owner.setAddressLine2(structuredAddress && !normalizedAddressLine2.isEmpty()
274	            ? normalizedAddressLine2 : null);
275	        owner.setTelephone(normalizedTelephone);
276	        owner.setEmail(normalizedEmail);
277	        owner.setHouseholdId(householdId);
278	        // Record how many existing owners (before this create) share this owner's first and last
279	        // name, compared case-insensitively. Computed against the current owners so the new owner
280	        // itself is never counted.
281	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
282	        // Record the size of this owner's household (owners sharing the same householdId) after this
283	        // create: the existing members already stamped with the shared identifier plus this new
284	        // owner. An owner not admitted into any household is a household of one.
285	        owner.setHouseholdSize(countHouseholdMembers(householdId) + 1);
286	        // Cap the new owner's membership level at one above the current maximum membership level
287	        // among their existing household members (members already carrying this household id). The cap
288	        // applies to an owner joining an existing household on their own; an explicitly declared
289	        // 'sharesHousehold' member keeps its full points-based level. When there is no existing
290	        // household member, no cap applies and the level is left uncapped.
291	        owner.setMembershipLevelCap(sharesHousehold ? null : householdMembershipLevelCap(householdId));
292	        // Persist the bulk-signup flag computed above so it is returned on subsequent reads.
293	        owner.setBulkSignupWarning(bulkSignupWarning);
294	        // Persist the capacity-warning flag computed above so it is returned on subsequent reads.
295	        owner.setCapacityWarning(capacityWarning);
296	        // Store the business-day-adjusted effective registration date computed above. This defaults
297	        // to the server's current date when none was supplied and rolls any weekend date forward to
298	        // the following Monday, so everything derived from it (e.g. the membership number's year
299	        // segment) uses the adjusted date.
300	        owner.setRegistrationDate(effectiveRegistrationDate);
301	        // Assign the customer code: '<REGION>-<HASH8>' where REGION is the region derived from the
302	        // owner's postcode (falling back to the city-to-region table, else 'UNKNOWN', matching the
303	        // locality derivation) and HASH8 is the first 8 upper-case hex characters of
304	        // SHA-256(normalizedTelephone + lastName). Sequence numbers are no longer used.
305	        // Compute the base code, then de-duplicate it: if the computed value collides with an
306	        // existing owner's customerCode, append '-<n>' using the smallest n of 2 or more that
307	        // yields a value no existing owner already carries.
308	        owner.setCustomerCode(deduplicateCustomerCode(customerCode(
309	            deriveRegion(owner.getPostcode(), owner.getCity()), normalizedTelephone, owner.getLastName())));
310	        // Soft-match detection: an owner that cleared the hard-duplicate check above may still
311	        // resemble an existing owner when its identity key differs but it shares that owner's
312	        // soundex(lastName) and postcode (a different telephone, and now a same-household-but-distinct
313	        // registration, both land here rather than being rejected). A declared household member
314	        // ('sharesHousehold') is never a suspected duplicate, so it is exempt. Flag a matched owner as
315	        // a possible duplicate, recording its id; otherwise the flag is false with no matched id.
316	        Owner possibleDuplicateOwner = sharesHousehold ? null : findPossibleDuplicate(
317	            owner.getLastName(), owner.getPostcode(), identityKey);
318	        owner.setPossibleDuplicate(possibleDuplicateOwner != null);
319	        owner.setPossibleDuplicateOf(possibleDuplicateOwner == null ? null : possibleDuplicateOwner.getId());
320	        this.clinicService.saveOwner(owner);
321	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
322	        // Emit an audit trail line for the successful create, carrying the owner id, the assigned
323	        // customer code, the effective registration date, the numeric membership level and the
324	        // assigned membership number.
325	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
326	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), ownerDto.getMembershipLevel(),
327	            ownerDto.getMembershipNumber());
328	        // Alongside the human-readable line, publish an immutable, machine-readable event describing
329	        // the create: a JSON object stamped with a process-wide monotonically increasing sequence, the
330	        // owner id, the owner's current primary identifier and its numeric membership level. The
331	        // primary identifier is the customerCode for now; when the customerCode is later unified into
332	        // the memberId, this field carries the memberId instead.
333	        Map<String, Object> ownerCreatedEvent = new LinkedHashMap<>();
334	        ownerCreatedEvent.put("seq", AUDIT_EVENT_SEQ.incrementAndGet());
335	        ownerCreatedEvent.put("ownerId", owner.getId());
336	        ownerCreatedEvent.put("customerCode", owner.getCustomerCode());
337	        ownerCreatedEvent.put("membershipLevel", ownerDto.getMembershipLevel());
338	        ownerCreatedEvent.put("event", "OWNER_CREATED");
339	        AUDIT.info(AUDIT_MAPPER.writeValueAsString(ownerCreatedEvent));
340	        headers.setLocation(UriComponentsBuilder.newInstance()
341	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
342	        // Remember the created owner against its idempotency key (when one was supplied) so a later
343	        // create repeating the same key returns this same owner rather than creating a duplicate.
344	        if (idempotencyKey != null) {
345	            idempotentCreations.put(idempotencyKey, ownerDto);
346	        }
347	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
348	    }
