448	    /**
449	     * Read the {@code Idempotency-Key} header from the current request, or {@code null} when the
450	     * header is absent, blank, or no request is bound to the thread. The header is not part of the
451	     * generated API signature, so it is read from the ambient request rather than a method parameter.
452	     */
453	    private static String currentIdempotencyKey() {
454	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
455	        if (!(attributes instanceof ServletRequestAttributes servletAttributes)) {
456	            return null;
457	        }
458	        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
459	        return isBlank(key) ? null : key;
460	    }
461	
462	    private static boolean isBlank(String value) {
463	        return value == null || value.trim().isEmpty();
464	    }
