466	    /**
467	     * Normalize an owner identity field for household-duplicate comparison: trim, collapse every
468	     * run of whitespace to a single space, and lower-case. Used so that last name and address are
469	     * compared case-insensitively with collapsed whitespace.
470	     */
471	    private static String collapse(String value) {
472	        if (value == null) {
473	            return "";
474	        }
475	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
476	    }
477	
478	    /**
479	     * Common street-type abbreviations expanded during address normalization.
480	     */
481	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
482	        "ST", "STREET",
483	        "RD", "ROAD",
484	        "AVE", "AVENUE");
485	
486	    /**
487	     * Normalize an owner address into its canonical stored/compared form: trim, collapse every run
488	     * of whitespace to a single space, upper-case, and expand common street-type abbreviations
489	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). Returns an empty string for
490	     * a {@code null} or blank input. The transformation is idempotent, so an already-normalized
491	     * address maps to itself.
492	     */
493	    private static String normalizeAddress(String value) {
494	        if (value == null) {
495	            return "";
496	        }
497	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
498	        if (collapsed.isEmpty()) {
499	            return "";
500	        }
501	        String[] tokens = collapsed.split(" ");
502	        StringBuilder sb = new StringBuilder(collapsed.length());
503	        for (int i = 0; i < tokens.length; i++) {
504	            if (i > 0) {
505	                sb.append(' ');
506	            }
507	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
508	        }
509	        return sb.toString();
510	    }
