512	    /**
513	     * Derive the stable household identifier shared by owners with the same normalized last name
514	     * and postcode. It is a deterministic function of those two values, so every member of a
515	     * household independently derives the same identifier: the first 12 upper-case hex characters
516	     * of {@code SHA-256(normalizedLastName + '|' + postcode)}. A {@code null} postcode contributes
517	     * an empty segment.
518	     */
519	    private static String householdId(String normalizedLastName, String postcode) {
520	        try {
521	            byte[] digest = MessageDigest.getInstance("SHA-256")
522	                .digest((normalizedLastName + "|" + (postcode == null ? "" : postcode))
523	                    .getBytes(StandardCharsets.UTF_8));
524	            StringBuilder sb = new StringBuilder(digest.length * 2);
525	            for (byte b : digest) {
526	                sb.append(String.format("%02x", b));
527	            }
528	            return sb.substring(0, 12).toUpperCase();
529	        }
530	        catch (NoSuchAlgorithmException e) {
531	            throw new IllegalStateException("SHA-256 not available", e);
532	        }
533	    }
534	
535	    /**
536	     * Derive the identity key into which all duplicate detection is consolidated: the full lower-case
537	     * hex SHA-256 over {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. A
538	     * null email or last name contributes an empty segment. Two owners are duplicates only when their
539	     * whole identity keys are equal. Delegates to {@link IdentityKeys#identityKey} so the value here
540	     * matches the one the mapper exposes on the owner DTO.
541	     */
542	    private static String identityKey(String telephone, String email, String lastName) {
543	        return IdentityKeys.identityKey(telephone, email, lastName);
544	    }
