546	    /**
547	     * Count the existing owners that share the given first and last name, compared
548	     * case-insensitively. Called before the new owner is saved, so the returned value reflects the
549	     * namesakes that already existed at creation time (the new owner itself is not included).
550	     */
551	    private int countNamesakes(String firstName, String lastName) {
552	        return (int) this.clinicService.findAllOwners().stream()
553	            .filter(existing -> existing.getFirstName() != null && existing.getLastName() != null)
554	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName)
555	                && existing.getLastName().equalsIgnoreCase(lastName))
556	            .count();
557	    }
558	
559	    /**
560	     * Count the existing owners that already belong to the given household (i.e. carry the same
561	     * non-null householdId). Called after any existing members have been backfilled with the shared
562	     * identifier but before the new owner is saved, so the returned value reflects the members that
563	     * already existed at creation time (the new owner itself is not included). Returns 0 when the
564	     * new owner is not part of any household ({@code householdId} is null).
565	     */
566	    private int countHouseholdMembers(String householdId) {
567	        if (householdId == null) {
568	            return 0;
569	        }
570	        return (int) this.clinicService.findAllOwners().stream()
571	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
572	            .count();
573	    }
574	
575	    /**
576	     * Compute the membership-level cap for a new owner joining the given household: one above the
577	     * current maximum membership level among the existing (non-deleted) members already carrying
578	     * this household id, using each member's effective (already-capped) level as returned to
579	     * clients. Returns {@code null} when the household has no existing member, so no cap applies.
580	     */
581	    private Integer householdMembershipLevelCap(String householdId) {
582	        if (householdId == null) {
583	            return null;
584	        }
585	        java.util.OptionalInt maxLevel = this.clinicService.findAllOwners().stream()
586	            .filter(existing -> !existing.isDeleted())
587	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
588	            .mapToInt(existing -> ownerMapper.membershipLevel(existing))
589	            .max();
590	        return maxLevel.isPresent() ? maxLevel.getAsInt() + 1 : null;
591	    }
592	
593	    /**
594	     * Find an existing owner that this new owner is a possible (soft) duplicate of: one whose
595	     * {@code soundex(lastName)} and postcode match the new owner's while its identity key differs (so
596	     * the two are not the same identity, which would already have been rejected as a 409). When
597	     * several existing owners match, the earliest (lowest id) is returned so the result is
598	     * deterministic. Returns {@code null} when there is no such owner — including when the new owner
599	     * has no last name or postcode, since a shared postcode is required to match.
600	     */
601	    private Owner findPossibleDuplicate(String lastName, String postcode, String identityKey) {
602	        if (isBlank(lastName) || isBlank(postcode)) {
603	            return null;
604	        }
605	        String soundex = IdentityKeys.soundex(lastName);
606	        return this.clinicService.findAllOwners().stream()
607	            .filter(existing -> !existing.isDeleted())
608	            .filter(existing -> soundex.equals(IdentityKeys.soundex(existing.getLastName())))
609	            .filter(existing -> postcode.equals(existing.getPostcode()))
610	            .filter(existing -> !identityKey.equals(
611	                identityKey(existing.getTelephone(), existing.getEmail(), existing.getLastName())))
612	            .min(java.util.Comparator.comparing(Owner::getId))
613	            .orElse(null);
614	    }
