665	    /** Fixed public holidays the business-day roll skips. */
666	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
667	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
668	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
669	
670	    /**
671	     * Roll a date forward onto a business day: Saturdays, Sundays and listed public holidays are
672	     * advanced one day at a time until a non-weekend, non-holiday day is reached, while an ordinary
673	     * business day is returned unchanged. Used so the effective registration date (whether supplied
674	     * or defaulted) always falls on a business day.
675	     */
676	    private static LocalDate toBusinessDay(LocalDate date) {
677	        while (isWeekendOrHoliday(date)) {
678	            date = date.plusDays(1);
679	        }
680	        return date;
681	    }
682	
683	    private static boolean isWeekendOrHoliday(LocalDate date) {
684	        return switch (date.getDayOfWeek()) {
685	            case SATURDAY, SUNDAY -> true;
686	            default -> PUBLIC_HOLIDAYS.contains(date);
687	        };
688	    }
689	
690	    /**
691	     * Build the customer code for a new owner: {@code '<REGION>-<HASH8>'} where REGION is the region
692	     * derived from the owner's postcode/city and HASH8 is the first 8 upper-case hex characters of
693	     * {@code SHA-256(normalizedTelephone + lastName)} (e.g. {@code 'NSW-1A2B3C4D'}).
694	     */
695	    private static String customerCode(String region, String normalizedTelephone, String lastName) {
696	        return region + "-" + hash8(normalizedTelephone + (lastName == null ? "" : lastName));
697	    }
698	
699	    /**
700	     * Ensure the computed customer code is unique across existing owners. When {@code base} is
701	     * already free it is returned unchanged; otherwise {@code '-<n>'} is appended using the smallest
702	     * {@code n} of 2 or more that produces a value no existing owner already carries.
703	     */
704	    private String deduplicateCustomerCode(String base) {
705	        java.util.Set<String> inUse = this.clinicService.findAllOwners().stream()
706	            .map(Owner::getCustomerCode)
707	            .filter(java.util.Objects::nonNull)
708	            .collect(java.util.stream.Collectors.toSet());
709	        if (!inUse.contains(base)) {
710	            return base;
711	        }
712	        int n = 2;
713	        while (inUse.contains(base + "-" + n)) {
714	            n++;
715	        }
716	        return base + "-" + n;
717	    }
718	
719	    /**
720	     * First 8 upper-case hex characters of {@code SHA-256(input)}.
721	     */
722	    private static String hash8(String input) {
723	        try {
724	            byte[] digest = MessageDigest.getInstance("SHA-256")
725	                .digest(input.getBytes(StandardCharsets.UTF_8));
726	            StringBuilder sb = new StringBuilder(digest.length * 2);
727	            for (byte b : digest) {
728	                sb.append(String.format("%02x", b));
729	            }
730	            return sb.substring(0, 8).toUpperCase();
731	        }
732	        catch (NoSuchAlgorithmException e) {
733	            throw new IllegalStateException("SHA-256 not available", e);
734	        }
735	    }
736	
737	    /**
738	     * Derive the owner's region, preferring the postcode: look up the region by postcode range first
739	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), then fall back to the city-to-region table
740	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD) when the postcode is absent or in no known
741	     * range. Returns {@code 'UNKNOWN'} when neither source resolves a region. This mirrors the
742	     * mapper's locality derivation, so the customer code's region segment and the owner's locality
743	     * always agree.
744	     */
745	    private static String deriveRegion(String postcode, String city) {
746	        if (postcode != null && postcode.matches("\\d{4}")) {
747	            int value = Integer.parseInt(postcode);
748	            for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
749	                int[] range = entry.getValue();
750	                if (value >= range[0] && value <= range[1]) {
751	                    return entry.getKey();
752	                }
753	            }
754	        }
755	        if (city == null) {
756	            return "UNKNOWN";
757	        }
758	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
759	    }
760	
761	    /**
762	     * The fixed city-to-region table used to validate a supplied postcode against the owner's city
763	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD). A city not present here has no known region
764	     * and accepts any 4-digit postcode.
765	     */
766	    private static final Map<String, String> CITY_REGION = Map.of(
767	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
768	
769	    /**
770	     * The fixed region-to-postcode ranges (inclusive): NSW 2000-2099, VIC 3000-3099, QLD 4000-4099.
771	     * Each entry is a two-element {@code {low, high}} array.
772	     */
773	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
774	        "NSW", new int[] {2000, 2099},
775	        "VIC", new int[] {3000, 3099},
776	        "QLD", new int[] {4000, 4099});
777	
778	    /**
779	     * Validate an optional owner postcode. Does nothing when no postcode was supplied (the field is
780	     * optional and the request contract stays backward-compatible). When supplied it must be exactly
781	     * 4 digits and, if the city maps to a known region, must fall within that region's inclusive
782	     * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any
783	     * 4-digit postcode. A malformed or out-of-range postcode throws an
784	     * {@link InvalidOwnerFieldsException} so the request is rejected with a 400.
785	     */
786	    private static void validatePostcode(String city, String postcode) {
787	        if (postcode == null || postcode.isEmpty()) {
788	            return;
789	        }
790	        if (!postcode.matches("\\d{4}")) {
791	            throw new InvalidOwnerFieldsException(List.of("postcode"));
792	        }
793	        String region = city == null ? null : CITY_REGION.get(city);
794	        if (region == null) {
795	            return;
796	        }
797	        int[] range = REGION_POSTCODES.get(region);
798	        int value = Integer.parseInt(postcode);
799	        if (value < range[0] || value > range[1]) {
800	            throw new InvalidOwnerFieldsException(List.of("postcode"));
801	        }
802	    }
803	
804	    /**
805	     * Required national-number length for each E.164 country calling code we validate: a
806	     * {@code '+61'} (Australia) number carries 9 national digits and a {@code '+1'} (NANP) number
807	     * carries 10. Country codes not listed here are accepted at any (generally valid) length.
808	     */
809	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
810	        "1", 10,
811	        "61", 9);
812	
813	    /**
814	     * Convert a raw telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
815	     * {@code '+'} with its country code is preserved; otherwise the Australian country code
816	     * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national digits.
817	     * The result must be a {@code '+'} followed by 8 to 15 digits, and for a recognised country code
818	     * its national-number length must match ({@code '+61'} requires 9 national digits, {@code '+1'}
819	     * requires 10); otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is
820	     * rejected with a 400.
821	     */
822	    private static String toE164(String raw) {
823	        String cleaned = raw.trim().replaceAll("[\\s()\\-]", "");
824	        boolean hasCountryCode = cleaned.startsWith("+");
825	        String digits = hasCountryCode ? cleaned.substring(1) : cleaned;
826	        if (!digits.matches("\\d+")) {
827	            throw new InvalidOwnerFieldsException(List.of("telephone"));
828	        }
829	        if (!hasCountryCode) {
830	            if (digits.startsWith("0")) {
831	                digits = digits.substring(1);
832	            }
833	            digits = "61" + digits;
834	        }
835	        if (digits.length() < 8 || digits.length() > 15) {
836	            throw new InvalidOwnerFieldsException(List.of("telephone"));
837	        }
838	        // For a recognised country code, the national number (the digits after the code) must be
839	        // exactly the expected length for that country. Match the longest known code so a shorter
840	        // code that is a prefix of another cannot mask it.
841	        for (int codeLength = 3; codeLength >= 1; codeLength--) {
842	            if (digits.length() <= codeLength) {
843	                continue;
844	            }
845	            String countryCode = digits.substring(0, codeLength);
846	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
847	            if (requiredNationalLength != null) {
848	                if (digits.length() - codeLength != requiredNationalLength) {
849	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
850	                }
851	                break;
852	            }
853	        }
854	        return "+" + digits;
855	    }
856	
857	    /**
858	     * Pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
859	     * and a domain with at least one dot-separated label, none of which contain whitespace or
860	     * a second {@code @}. This is deliberately permissive but rejects obviously malformed input.
861	     */
862	    private static final Pattern EMAIL_PATTERN =
863	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
864	
865	    /**
866	     * Disposable email domains that are not accepted for an owner. An email whose domain (the part
867	     * after the {@code @}, compared case-insensitively) is on this blocklist is rejected with a 400.
868	     */
869	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
870	        "mailinator.com", "tempmail.com", "guerrillamail.com");
871	
872	    /**
873	     * Validate and normalize an optional owner email. Returns {@code null} when no email was
874	     * supplied (the field is optional). When supplied it must be a syntactically valid address whose
875	     * domain is not on the disposable-domain blocklist, otherwise an
876	     * {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a 400. A valid
877	     * address is returned lower-cased.
878	     */
879	    private static String normalizeEmail(String email) {
880	        if (email == null || email.isEmpty()) {
881	            return null;
882	        }
883	        String trimmed = email.trim();
884	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
885	            throw new InvalidOwnerFieldsException(List.of("email"));
886	        }
887	        String normalized = trimmed.toLowerCase();
888	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
889	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
890	            throw new InvalidOwnerFieldsException(List.of("email"));
891	        }
892	        return normalized;
893	    }
894	}
